import{_ as e,a as r,c as d,ac as s}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Redis String（字符串） · 1. 定位：解决什么问题至2. 命令速查与示例","description":"简单值、计数、会话与短期占位，包括基本操作、适用场景和使用边界。","frontmatter":{"title":"Redis String（字符串） · 1. 定位：解决什么问题至2. 命令速查与示例","description":"简单值、计数、会话与短期占位，包括基本操作、适用场景和使用边界。","splitFrom":"middleware/redis/plus/subjects/string.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis String（字符串）","summary":"简单值、计数、会话与短期占位，包括基本操作、适用场景和使用边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis String（字符串）","link":"/middleware/redis/plus/subjects/string"},"next":{"text":"Redis String（字符串） · 3. 底层编码与内存至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/string-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis String（字符串）","link":"/middleware/redis/plus/subjects/string"},"next":{"text":"Redis String（字符串） · 3. 底层编码与内存至8. Go 客户端与最佳实践","link":"/middleware/redis/plus/subjects/string-part-02"}},"headers":[],"relativePath":"middleware/redis/plus/subjects/string-part-01.md","filePath":"middleware/redis/plus/subjects/string-part-01.md"}'),a={name:"middleware/redis/plus/subjects/string-part-01.md"};function n(i,t,o,l,c,p){return r(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="redis-string-字符串-·-1-定位-解决什么问题至2-命令速查与示例" tabindex="-1">Redis String（字符串） · 1. 定位：解决什么问题至2. 命令速查与示例 <a class="header-anchor" href="#redis-string-字符串-·-1-定位-解决什么问题至2-命令速查与示例" aria-label="Permalink to &quot;Redis String（字符串） · 1. 定位：解决什么问题至2. 命令速查与示例&quot;">​</a></h1><p><a href="/middleware/redis/plus/subjects/string">返回分篇目录</a></p><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="string" tabindex="-1">Redis String（字符串） <a class="header-anchor" href="#string" aria-label="Permalink to &quot;Redis String（字符串） {#string}&quot;">​</a></h2><p>本文按 Redis 8.2.10 核对编码与配置默认值；命令的引入版本另行标注。生产配置可能不同，可通过 CONFIG GET 查询。示例面向独立实验服务，运行结果和内存数字未在本次实测。</p><h2 id="position" tabindex="-1">1. 定位：解决什么问题 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;1. 定位：解决什么问题 {#position}&quot;">​</a></h2><p>String 是一个整体字节串，适合会话、序列化缓存和计数。需要按字段更新对象时比较 Hash；需要唯一成员及排名时比较 Set / ZSet。把 JSON 存入 String 只约定序列化格式，不会自动获得字段级命令。</p><h3 id="基本操作示例" tabindex="-1">基本操作示例 <a class="header-anchor" href="#基本操作示例" aria-label="Permalink to &quot;基本操作示例 {#基本操作示例}&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET learn:types:count 10</span></span>
<span class="line"><span>INCRBY learn:types:count 2</span></span>
<span class="line"><span>GET learn:types:count</span></span></code></pre></div><p>预期最后读取到 <code>12</code>。<code>INCRBY</code> 在服务端完成加法，避免客户端先读再写的覆盖问题；值必须满足整数格式和范围要求。不要把一次命令的原子性推广成整个业务流程的原子性。</p><p>参考：<a href="https://redis.io/docs/latest/develop/data-types/strings/" target="_blank" rel="noopener noreferrer">String</a>。</p><h3 id="游戏与后端场景" tabindex="-1">游戏与后端场景 <a class="header-anchor" href="#游戏与后端场景" aria-label="Permalink to &quot;游戏与后端场景 {#游戏与后端场景}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>建模与操作</th><th>需要补齐的业务规则</th></tr></thead><tbody><tr><td>会话令牌</td><td><code>SET sess:token uid EX 3600</code></td><td>token 应不可预测；过期、撤销和续期需定义清楚</td></tr><tr><td>幂等请求</td><td><code>SET idem:req-id processing NX EX 86400</code></td><td>未取得占位不代表业务已成功；还需存处理状态、结果和请求摘要</td></tr><tr><td>固定窗口限流</td><td><code>INCR</code>，首次写入设置过期</td><td>增加与首次过期设置需在同一 Lua 操作中完成，避免永久计数键</td></tr><tr><td>缓存击穿保护</td><td>读缓存未命中后短租约合并回源</td><td>失败时释放或等待租约到期，回填须考虑旧值覆盖</td></tr><tr><td>每日任务</td><td>键包含业务日期，使用 <code>EXPIREAT</code></td><td>按约定时区计算下一次重置，不把一天固定当成 86400 秒</td></tr><tr><td>分布式锁</td><td><code>SET lock:x token NX PX 10000</code></td><td>只由持有同一 token 的调用者释放，处理租约过期和故障切换</td></tr></tbody></table><h2 id="commands" tabindex="-1">2. 命令速查与示例 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;2. 命令速查与示例 {#commands}&quot;">​</a></h2><p>按用途分组，共 <strong>22 项</strong>，覆盖 Redis 8.2.10 的本类型命令及子命令。点击命令名查看官方参数。示例在 redis-cli 中逐行输入，<strong>每次换例子前重置下面的教学数据</strong>。</p><details class="details custom-block"><summary>准备与重置示例数据</summary><p>在独立实验实例的 <strong>redis-cli 交互模式</strong>逐行输入，避免 shell 对引号、<code>&gt;</code>、<code>*</code>、括号等符号进行解释。<strong>每个例子独立使用；换例子前重新执行下面的准备段</strong>，否则删除、弹出、过期和修改操作会影响后续结果。准备段仅重置列出的教学键，确认这些键不承载业务数据。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNLINK learn:{string}:text learn:{string}:count learn:{string}:ratio learn:{string}:left learn:{string}:right learn:{string}:new1 learn:{string}:new2</span></span>
<span class="line"><span>SET learn:{string}:text hello</span></span>
<span class="line"><span>SET learn:{string}:count 10</span></span>
<span class="line"><span>SET learn:{string}:ratio 1.5</span></span>
<span class="line"><span>SET learn:{string}:left abcdef</span></span>
<span class="line"><span>SET learn:{string}:right ace</span></span></code></pre></div><p>示例的返回说明以刚完成准备段为前提，随机结果与剩余 TTL 不固定。带同一 <code>{...}</code> 的教学键便于在 Cluster 中满足相关多键操作的同槽要求。</p></details><h3 id="读写与子串" tabindex="-1">读写与子串 <a class="header-anchor" href="#读写与子串" aria-label="Permalink to &quot;读写与子串 {#读写与子串}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-set"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/set.json" target="_blank" rel="noopener noreferrer">SET</a><br>写入或覆盖字符串</td><td><code>SET learn:{string}:text world GET</code><br>返回旧字符串 hello；GET 选项从 6.2 起支持。</td><td>O(1)</td></tr><tr><td><span id="cmd-get"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/get.json" target="_blank" rel="noopener noreferrer">GET</a><br>读取字符串</td><td><code>GET learn:{string}:text</code><br>返回 hello；不存在时返回空值。</td><td>O(1)</td></tr><tr><td><span id="cmd-append"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/append.json" target="_blank" rel="noopener noreferrer">APPEND</a><br>追加内容</td><td><code>APPEND learn:{string}:text &quot;!&quot;</code><br>字符串变成 hello!，返回新长度 6。</td><td>小追加摊还 O(1)</td></tr><tr><td><span id="cmd-strlen"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/strlen.json" target="_blank" rel="noopener noreferrer">STRLEN</a><br>读取字节长度</td><td><code>STRLEN learn:{string}:text</code><br>返回 5；不是 Unicode 字符数。</td><td>O(1)</td></tr><tr><td><span id="cmd-getrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/getrange.json" target="_blank" rel="noopener noreferrer">GETRANGE</a><br>读取字节区间</td><td><code>GETRANGE learn:{string}:text 0 1</code><br>返回 he，结束下标包含在内。</td><td>O(B)</td></tr><tr><td><span id="cmd-setrange"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/setrange.json" target="_blank" rel="noopener noreferrer">SETRANGE</a><br>覆盖指定偏移的字节</td><td><code>SETRANGE learn:{string}:text 1 a</code><br>得到 hallo，返回长度 5；大偏移可能扩容。</td><td>O(B)</td></tr><tr><td><span id="cmd-mget"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/mget.json" target="_blank" rel="noopener noreferrer">MGET</a><br>批量读取</td><td><code>MGET learn:{string}:text learn:{string}:count</code><br>依次返回 hello 与 10。</td><td>O(K)</td></tr><tr><td><span id="cmd-mset"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/mset.json" target="_blank" rel="noopener noreferrer">MSET</a><br>批量设置</td><td><code>MSET learn:{string}:text hi learn:{string}:count 20</code><br>返回 OK，两个键一起设置。</td><td>O(K)</td></tr><tr><td><span id="cmd-msetnx"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/msetnx.json" target="_blank" rel="noopener noreferrer">MSETNX</a><br>所有键不存在时批量写入</td><td><code>MSETNX learn:{string}:new1 a learn:{string}:new2 b</code><br>返回 1；任意目标已存在则全部不写并返回 0。</td><td>O(K)</td></tr><tr><td><span id="cmd-getdel"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/getdel.json" target="_blank" rel="noopener noreferrer">GETDEL</a><br>读取并删除</td><td><code>GETDEL learn:{string}:text</code><br>返回 hello 并删除键。</td><td>O(1)</td></tr><tr><td><span id="cmd-getex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/getex.json" target="_blank" rel="noopener noreferrer">GETEX</a><br>读取并设置过期</td><td><code>GETEX learn:{string}:text EX 60</code><br>返回 hello，并设置整个键 60 秒过期。</td><td>O(1)</td></tr><tr><td><span id="cmd-lcs"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/lcs.json" target="_blank" rel="noopener noreferrer">LCS</a><br>最长公共子序列</td><td><code>LCS learn:{string}:left learn:{string}:right LEN</code><br>abcdef 与 ace 的最长公共子序列长度为 3。</td><td>O(N×M)</td></tr></tbody></table><h3 id="数值运算" tabindex="-1">数值运算 <a class="header-anchor" href="#数值运算" aria-label="Permalink to &quot;数值运算 {#数值运算}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-incr"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/incr.json" target="_blank" rel="noopener noreferrer">INCR</a><br>整数加一</td><td><code>INCR learn:{string}:count</code><br>10 变成 11，返回 11。</td><td>O(1)</td></tr><tr><td><span id="cmd-incrby"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/incrby.json" target="_blank" rel="noopener noreferrer">INCRBY</a><br>整数增加指定值</td><td><code>INCRBY learn:{string}:count 5</code><br>10 变成 15。</td><td>O(1)</td></tr><tr><td><span id="cmd-decr"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/decr.json" target="_blank" rel="noopener noreferrer">DECR</a><br>整数减一</td><td><code>DECR learn:{string}:count</code><br>10 变成 9。</td><td>O(1)</td></tr><tr><td><span id="cmd-decrby"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/decrby.json" target="_blank" rel="noopener noreferrer">DECRBY</a><br>整数减少指定值</td><td><code>DECRBY learn:{string}:count 3</code><br>10 变成 7。</td><td>O(1)</td></tr><tr><td><span id="cmd-incrbyfloat"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/incrbyfloat.json" target="_blank" rel="noopener noreferrer">INCRBYFLOAT</a><br>浮点数增加</td><td><code>INCRBYFLOAT learn:{string}:ratio 0.25</code><br>1.5 变成 1.75；不用于精确资金账目。</td><td>O(1)</td></tr></tbody></table><h3 id="旧版兼容命令" tabindex="-1">旧版兼容命令 <a class="header-anchor" href="#旧版兼容命令" aria-label="Permalink to &quot;旧版兼容命令 {#旧版兼容命令}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令与用途</th><th>示例与结果</th><th>复杂度</th></tr></thead><tbody><tr><td><span id="cmd-getset"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/getset.json" target="_blank" rel="noopener noreferrer">GETSET</a><br>旧式读取并覆盖</td><td><code>GETSET learn:{string}:text world</code><br>返回 hello；新代码优先 SET ... GET。</td><td>O(1)</td></tr><tr><td><span id="cmd-setnx"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/setnx.json" target="_blank" rel="noopener noreferrer">SETNX</a><br>旧式仅不存在时写入</td><td><code>SETNX learn:{string}:new1 value</code><br>返回 1；新代码优先 SET ... NX，可同时指定 TTL。</td><td>O(1)</td></tr><tr><td><span id="cmd-setex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/setex.json" target="_blank" rel="noopener noreferrer">SETEX</a><br>旧式写入并设置秒过期</td><td><code>SETEX learn:{string}:new1 60 value</code><br>返回 OK；新代码用 SET key value EX 60。</td><td>O(1)</td></tr><tr><td><span id="cmd-psetex"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/psetex.json" target="_blank" rel="noopener noreferrer">PSETEX</a><br>旧式写入并设置毫秒过期</td><td><code>PSETEX learn:{string}:new1 60000 value</code><br>返回 OK；新代码用 SET key value PX 60000。</td><td>O(1)</td></tr><tr><td><span id="cmd-substr"></span><a href="https://github.com/redis/redis/blob/8.2.10/src/commands/substr.json" target="_blank" rel="noopener noreferrer">SUBSTR</a><br>旧式读取子串</td><td><code>SUBSTR learn:{string}:text 0 1</code><br>返回 he；新代码用 GETRANGE。</td><td>O(B)</td></tr></tbody></table><details class="details custom-block"><summary>版本与复杂度补充</summary><p>下表保留每条命令的引入版本、兼容状态及复杂度符号含义；复杂度不包含全部网络传输、内存分配和等待成本。</p><table tabindex="0"><thead><tr><th>命令</th><th>引入版本与状态</th><th>复杂度说明</th></tr></thead><tbody><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-set">SET</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-get">GET</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-append">APPEND</a></td><td>2.0.0</td><td>小追加摊还 O(1)；扩容和大字节追加还有复制成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-strlen">STRLEN</a></td><td>2.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-getrange">GETRANGE</a></td><td>2.4.0</td><td>O(B)，B 为返回字节数；小范围可近似看作常数开销。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-setrange">SETRANGE</a></td><td>2.2.0</td><td>O(B)，B 为写入字节数；扩容和填零还有额外成本。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-mget">MGET</a></td><td>1.0.0</td><td>O(K)，K 为本次键数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-mset">MSET</a></td><td>1.0.1</td><td>O(K)，K 为本次键数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-msetnx">MSETNX</a></td><td>1.0.1</td><td>O(K)，K 为本次键数。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-getdel">GETDEL</a></td><td>6.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-getex">GETEX</a></td><td>6.2.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-lcs">LCS</a></td><td>7.0.0</td><td>O(N×M)，N、M 为两个字符串长度。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-incr">INCR</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-incrby">INCRBY</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-decr">DECR</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-decrby">DECRBY</a></td><td>1.0.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-incrbyfloat">INCRBYFLOAT</a></td><td>2.6.0</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-getset">GETSET</a></td><td>1.0.0；从 6.2.0 起弃用（兼容保留）</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-setnx">SETNX</a></td><td>1.0.0；从 2.6.12 起弃用（兼容保留）</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-setex">SETEX</a></td><td>2.0.0；从 2.6.12 起弃用（兼容保留）</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-psetex">PSETEX</a></td><td>2.6.0；从 2.6.12 起弃用（兼容保留）</td><td>O(1)。大值复制、扩容、网络输出和等待时间需另外考虑。</td></tr><tr><td><a href="/middleware/redis/plus/subjects/string-part-01#cmd-substr">SUBSTR</a></td><td>1.0.0；从 2.0.0 起弃用（兼容保留）</td><td>O(B)，B 为返回字节数；小范围可近似看作常数开销。</td></tr></tbody></table></details><p>SET ... GET 从 6.2 起支持，NX 与 GET 联用从 7.0 起支持；KEEPTTL 从 6.0 起支持。条件写入要按具体选项判断返回语义。</p><p>通用键操作见<a href="/middleware/redis/base/basic/keys">键与过期时间</a>，这里集中列出类型自身的命令。</p>`,25)])])}const g=e(a,[["render",n]]);export{h as __pageData,g as default};
